select pid, state, now() - query_start as running, wait_event_type, wait_event, left(query, 110) as query from pg_stat_activity where state <> 'idle' and pid <> pg_backend_pid() order by query_start limit 12;
explain analyze select public.related_notices((select jsonb_agg(jsonb_build_object('authority', authority_name, 'budget', b, 'budget_ex', ex, 'd_from', publication_date - 30, 'd_to', publication_date + 400)) from (select authority_name, publication_date, coalesce(nullif(budget_inc_vat,0), nullif(budget_ex_vat,0), nullif(budget_unknown_vat,0)) as b, nullif(budget_ex_vat,0) as ex from public.procurements_compact where document_category = 'declaration' order by publication_date desc nulls last limit 100) s));
explain analyze select public.market_overview_fast(null, null, null, null, true)
